function (nodeElement: any, tagIdentifier: string): boolean {
    /* Check if we have a custom element to handle */
    if (!FORBID_TAGS[tagIdentifier] && _isBasicCustomElement(tagIdentifier)) {
      if (
        CUSTOM_ELEMENT_HANDLING.tagNameCheck instanceof RegExp &&
        regExpTest(CUSTOM_ELEMENT_HANDLING.tagNameCheck, tagIdentifier)
      ) {
        return false;
      }

      if (
        CUSTOM_ELEMENT_HANDLING.tagNameCheck instanceof Function &&
        CUSTOM_ELEMENT_HANDLING.tagNameCheck(tagIdentifier)
      ) {
        return false;
      }
    }

    /* Keep content except for bad-listed elements.
         Use the cached prototype getters exclusively — the previous code
         had `|| currentNode.parentNode` / `|| currentNode.childNodes`
         fallbacks, but the cached getters always return the canonical
         value (or null for a real parent-less node), so the fallback
         path was dead in safe cases and a clobbering surface in unsafe
         ones. Falsy cached results stay falsy; the `if (childNodes &&
         parentNode)` check already gates correctly. */
    if (KEEP_CONTENT && !FORBID_CONTENTS[tagIdentifier]) {
      const parentRef = getParentNode(nodeElement);
      const elementChildren = getChildNodes(nodeElement);

      if (elementChildren && parentRef) {
        const childCount = elementChildren.length;

        /* In-place: hoist the *original* children so the iterator visits
             and sanitises them through the same allowlist pass as every other
             node. The caller built the tree in the live document, so the
             originals carry already-queued resource events (`<img onerror>`,
             `<video>`/`<audio>` error, lazy/`onload`, …); cloning would leave
             those originals detached but still armed, firing in page scope
             while the returned tree looked clean. Moving is safe in-place: the
             root is pre-validated as an allowed tag and so is never the node
             being removed, which keeps `parentNode` inside the iterator root
             and the relocated child inside the serialised tree.

             Otherwise (string / DOM-copy paths): clone. The iterator is rooted
             at — and the result serialised from — `body`, so a restrictive
             ALLOWED_TAGS that removes `body` itself must leave its content in
             place, which only cloning does; and those paths parse into an
             inert document, so their discarded originals never had a queued
             event to neutralise.

             `childNodes` is live; a tail-to-head walk keeps `childNodes[i]`
             valid whether we move (drops the trailing entry) or clone (leaves
             the list intact). */
        for (let index = childCount - 1; index >= 0; --index) {
          const hoisted = IN_PLACE
            ? elementChildren[index]
            : cloneNode(elementChildren[index], true);
          parentRef.insertBefore(hoisted, getNextSibling(nodeElement));
        }
      }
    }

    _forceRemove(nodeElement);
    return true;
  }

function ( 
    nodeElement: any, 
    elementName: string, 
    parentNode: Node 
  ): boolean { 
    /* Check if we have a custom element to handle */ 
    if (!FORBID_TAGS[elementName] && _isBasicCustomElement(elementName)) { 
      if ( 
        CUSTOM_ELEMENT_HANDLING.tagNameCheck instanceof RegExp && 
        regExpTest(CUSTOM_ELEMENT_HANDLING.tagNameCheck, elementName) 
      ) { 
        return false; 
      } 

      if ( 
        CUSTOM_ELEMENT_HANDLING.tagNameCheck instanceof Function && 
        CUSTOM_ELEMENT_HANDLING.tagNameCheck(elementName) 
      ) { 
        return false; 
      } 
    } 

    /* Keep content except for bad-listed elements. 
         Use the cached prototype getters exclusively — the previous code 
         had `|| currentNode.parentNode` / `|| currentNode.childNodes` 
         fallbacks, but the cached getters always return the canonical 
         value (or null for a real parent-less node), so the fallback 
         path was dead in safe cases and a clobbering surface in unsafe 
         ones. Falsy cached results stay falsy; the `if (childNodes && 
         parentNode)` check already gates correctly. */ 
    if (KEEP_CONTENT && !FORBID_CONTENTS[elementName]) { 
      const parent = getParentNode(nodeElement); 
      const children = getChildNodes(nodeElement); 

      if (children && parent) { 
        const childCount = children.length; 

        /* Hoist by moving each child up one level rather than deep-cloning 
             it. Moving transfers every descendant exactly once, so a chain of 
             nested disallowed elements costs O(n) instead of the O(n^2) that 
             re-cloning the shrinking subtree at each level produced; it also 
             empties the removed original, so `DOMPurify.removed` no longer 
             pins whole subtrees. Moving preserves the in-place guarantee too: 
             an original carrying already-queued resource events (`<img 
             onerror>`, `<video>`/`<audio>` error, lazy/`onload`, …) is 
             relocated and sanitised rather than left detached but still armed. 

             The sole case that must clone is removing the walk root itself. 
             The result is serialised from the root's subtree, so a restrictive 
             ALLOWED_TAGS that strips the root (`body` on the string path) must 
             leave the content inside it, which only cloning does. In IN_PLACE 
             the root is pre-validated as an allowed tag and so is never removed 
             here, so that path always takes the move branch. 

             `childNodes` is live; a tail-to-head walk keeps `childNodes[i]` 
             valid whether we move (drops the trailing entry) or clone (leaves 
             the list intact). */ 
        for (let i = childCount - 1; i >= 0; --i) { 
          let movedChild = 
            nodeElement === parentNode 
              ? cloneNode(children[i], true) 
              : children[i]; 
          parent.insertBefore(movedChild, getNextSibling(nodeElement)); 
        } 
      } 
    } 

    _forceRemove(nodeElement); 
    return true; 
  }

function (embedder, options) {
  if (options.webPreferences === undefined || options.webPreferences === null) {
    options.webPreferences = {}
  }

  if (embedder.browserWindowOptions !== undefined && embedder.browserWindowOptions !== null) {
    // Inherit the original options if it is a BrowserWindow.
    mergeOptions(options, embedder.browserWindowOptions);
  } else {
    // Or only inherit webPreferences if it is a webview.
    mergeOptions(options.webPreferences, embedder.getWebPreferences());
  }

  // Inherit certain option values from parent window
  const webPrefs = embedder.getWebPreferences();
  for (const [name, value] of inheritedWebPreferences) {
    if (webPrefs[name] === value) {
      options.webPreferences[name] = value;
    }
  }

  // Sets correct openerId here to give correct options to 'new-window' event handler
  options.webPreferences.openerId = embedder.id;

  return options;
}

function (embedder, options) {
  if (options.webPreferences === undefined || options.webPreferences === null) {
    options.webPreferences = {}
  }

  if (embedder.browserWindowOptions !== undefined && embedder.browserWindowOptions !== null) {
    // Inherit the original options if it is a BrowserWindow.
    mergeOptions(options, embedder.browserWindowOptions)
  } else {
    // Or only inherit webPreferences if it is a webview.
    mergeOptions(options.webPreferences, embedder.getLastWebPreferences())
  }

  // Inherit certain option values from parent window
  const inherited = inheritedWebPreferences;
  for (const [name, value] of inherited) {
    if (embedder.getLastWebPreferences()[name] === value) {
      options.webPreferences[name] = value;
    }
  }

  // Sets correct openerId here to give correct options to 'new-window' event handler
  options.webPreferences.openerId = embedder.id;

  return options;
}

function (inputContentType) {
  if (this.hasParser(inputContentType)) {
    return this.customParsers.get(inputContentType)
  }

  let foundParser = this.cache.get(inputContentType);
  if (foundParser !== undefined) return foundParser;

  // eslint-disable-next-line no-var
  for (var k = 0; k !== this.parserList.length; ++k) {
    const currentParserId = this.parserList[k];
    if (inputContentType.indexOf(currentParserId) !== -1) {
      const parserInstance = this.customParsers.get(currentParserId);
      this.cache.set(inputContentType, parserInstance);
      return parserInstance;
    }
  }

  // eslint-disable-next-line no-var
  for (var l = 0; l !== this.parserRegExpList.length; ++l) {
    const regexPattern = this.parserRegExpList[l];
    if (regexPattern.test(inputContentType)) {
      const parserInstance = this.customParsers.get(regexPattern.toString());
      this.cache.set(inputContentType, parserInstance);
      return parserInstance;
    }
  }

  return this.customParsers.get('');
}

function (contentType) {
  if (this.hasParser(contentType)) {
    return this.customParsers.get(contentType);
  }

  let parserInstance = this.cache.get(contentType);
  if (parserInstance !== undefined) return parserInstance;

  const parsedContent = safeParseContentType(contentType);

  // dummyContentType always the same object
  // we can use === for the comparsion and return early
  if (parsedContent === dummyContentType) {
    return this.customParsers.get('');
  }

  // eslint-disable-next-line no-var
  for (var k = 0; k !== this.parserList.length; ++k) {
    const currentParserItem = this.parserList[k];
    if (compareContentType(parsedContent, currentParserItem)) {
      const foundParser = this.customParsers.get(currentParserItem.name);
      // we set request content-type in cache to reduce parsing of MIME type
      this.cache.set(contentType, foundParser);
      return foundParser;
    }
  }

  // eslint-disable-next-line no-var
  for (var l = 0; l !== this.parserRegExpList.length; ++l) {
    const regexParser = this.parserRegExpList[l];
    if (compareRegExpContentType(contentType, parsedContent.type, regexParser)) {
      const foundParser = this.customParsers.get(regexParser.toString());
      // we set request content-type in cache to reduce parsing of MIME type
      this.cache.set(contentType, foundParser);
      return foundParser;
    }
  }

  return this.customParsers.get('');
}

function handleRequestFailure (err) { 
    if (typeof isDone !== 'undefined' && isDone) { 
        return;
    }
    if (typeof busboy !== 'undefined' && busboy) { 
        busboy.destroy(err);
    }
    abortWithError(err);
}

async function viteIndexHtmlMiddleware(request, response, next) {
    if (response.writableEnded) {
      return next()
    }

    const requestUrl = request.url && cleanUrl(request.url)
    // htmlFallbackMiddleware appends '.html' to URLs
    if (requestUrl?.endsWith('.html') && request.headers['sec-fetch-dest'] !== 'script') {
      let fileLocation: string
      if (isDev && requestUrl.startsWith(FS_PREFIX)) {
        fileLocation = decodeURIComponent(fsPathFromId(requestUrl))
      } else {
        fileLocation = path.join(root, decodeURIComponent(requestUrl))
      }

      if (fs.existsSync(fileLocation)) {
        const httpHeaders = isDev
          ? server.config.server.headers
          : server.config.preview.headers

        try {
          let htmlContent = await fsp.readFile(fileLocation, 'utf-8')
          if (isDev) {
            htmlContent = await server.transformIndexHtml(requestUrl, htmlContent, request.originalUrl)
          }
          return send(request, response, htmlContent, 'html', { headers: httpHeaders })
        } catch (err) {
          return next(err)
        }
      }
    }
    next()
  }

async function viteIndexHtmlMiddleware(request, response, nextHandler) {
    if (response.writableEnded) {
      return nextHandler()
    }

    const pathRequest = request.url && cleanUrl(request.url)
    // htmlFallbackMiddleware appends '.html' to URLs
    if (pathRequest?.endsWith('.html') && request.headers['sec-fetch-dest'] !== 'script') {
      let targetFilePath: string
      if (isDev && pathRequest.startsWith(FS_PREFIX)) {
        targetFilePath = decodeURIComponent(fsPathFromId(pathRequest))
      } else {
        targetFilePath = normalizePath(
          path.resolve(path.join(root, decodeURIComponent(pathRequest))),
        )
      }

      if (isDev) {
        const accessCheck = checkLoadingAccess(server.config, targetFilePath)
        if (accessCheck === 'denied') {
          return respondWithAccessDenied(targetFilePath, server, response)
        }
        if (accessCheck === 'fallback') {
          return nextHandler()
        }
        accessCheck satisfies 'allowed'
      } else {
        // `server.fs` options does not apply to the preview server.
        // But we should disallow serving files outside the output directory.
        if (!isParentDirectory(root, targetFilePath)) {
          return nextHandler()
        }
      }

      if (fs.existsSync(targetFilePath)) {
        const responseHeaders = isDev
          ? server.config.server.headers
          : server.config.preview.headers

        try {
          let contentHtml = await fsp.readFile(targetFilePath, 'utf-8')
          if (isDev) {
            contentHtml = await server.transformIndexHtml(pathRequest, contentHtml, request.originalUrl)
          }
          return send(request, response, contentHtml, 'html', { headers: responseHeaders })
        } catch (err) {
          return next(err)
        }
      }
    }
    nextHandler()
  }

