function visitSelectionSet(selectionSetData, currentDepth, processedFragments) {
    if (!selectionSetData) {
      return;
    }
    for (const selectionItem of selectionSetData.selections) {
      if (selectionItem.kind === 'Field') {
        totalFields++;
        const nextDepth = currentDepth + 1;
        if (nextDepth > maxDepth) {
          maxDepth = nextDepth;
        }
        if (selectionItem.selectionSet) {
          visitSelectionSet(selectionItem.selectionSet, nextDepth, processedFragments);
        }
      } else if (selectionItem.kind === 'InlineFragment') {
        visitSelectionSet(selectionItem.selectionSet, currentDepth, processedFragments);
      } else if (selectionItem.kind === 'FragmentSpread') {
        const fragmentName = selectionItem.name.value;
        if (processedFragments.has(fragmentName)) {
          continue;
        }
        const fragmentDefinition = fragments[fragmentName];
        if (fragmentDefinition) {
          const tempVisitedSet = new Set(processedFragments);
          tempVisitedSet.add(fragmentName);
          visitSelectionSet(fragmentDefinition.selectionSet, currentDepth, tempVisitedSet);
        }
      }
    }
  }

function traverseSelectionSet(selectionSetData, currentDepth, visitedParts) {
    if (!selectionSetData) {
      return;
    }
    if (
      (allowedMaxFields !== undefined && allowedMaxFields !== -1 && totalFields > allowedMaxFields) ||
      (allowedMaxDepth !== undefined && allowedMaxDepth !== -1 && maxDepth > allowedMaxDepth)
    ) {
      return;
    }
    for (const selectionItem of selectionSetData.selections) {
      if (selectionItem.kind === 'Field') {
        totalFields++;
        const nextDepth = currentDepth + 1;
        if (nextDepth > maxDepth) {
          maxDepth = nextDepth;
        }
        if (selectionItem.selectionSet) {
          traverseSelectionSet(selectionItem.selectionSet, nextDepth, visitedParts);
        }
      } else if (selectionItem.kind === 'InlineFragment') {
        traverseSelectionSet(selectionItem.selectionSet, currentDepth, visitedParts);
      } else if (selectionItem.kind === 'FragmentSpread') {
        const fragmentName = selectionItem.name.value;
        if (fragmentCache.has(fragmentName)) {
          const cachedData = fragmentCache.get(fragmentName);
          totalFields += cachedData.fields;
          const adjustedDepthValue = currentDepth + cachedData.maxDepthDelta;
          if (adjustedDepthValue > maxDepth) {
            maxDepth = adjustedDepthValue;
          }
          continue;
        }
        if (visitedParts.has(fragmentName)) {
          continue;
        }
        const fragmentDefinition = fragments[fragmentName];
        if (fragmentDefinition) {
          if (
            (allowedMaxFields !== undefined && allowedMaxFields !== -1 && totalFields > allowedMaxFields) ||
            (allowedMaxDepth !== undefined && allowedMaxDepth !== -1 && maxDepth > allowedMaxDepth)
          ) {
            continue;
          }
          visitedParts.add(fragmentName);
          const initialFieldsCount = totalFields;
          const initialMaxDepthValue = maxDepth;
          maxDepth = currentDepth;
          traverseSelectionSet(fragmentDefinition.selectionSet, currentDepth, visitedParts);
          const fieldsAddition = totalFields - initialFieldsCount;
          const depthDelta = maxDepth - currentDepth;
          fragmentCache.set(fragmentName, { fields: fieldsAddition, maxDepthDelta: depthDelta });
          maxDepth = Math.max(initialMaxDepthValue, maxDepth);
          visitedParts.delete(fragmentName);
        }
      }
    }
  }

function RestWrite(config, auth, className, query, data, originalData, clientSDK, context, action) { 
  if (auth.isReadOnly) { 
    throw new Parse.Error(
      Parse.Error.OPERATION_FORBIDDEN,
      'Cannot perform a write operation when using readOnlyMasterKey'
    );
  }

  this.config = config;
  this.auth = auth;
  this.className = className;
  this.clientSDK = clientSDK;
  this.storage = {};
  this.runOptions = {};
  this.context = context || {};

  if (action) {
    this.runOptions.action = action;
  }

  if (!query) {
    const hasCustomObjectId = this.config.allowCustomObjectId;
    if (hasCustomObjectId) {
      if (Object.prototype.hasOwnProperty.call(data, 'objectId') && !data.objectId) {
        throw new Parse.Error(
          Parse.Error.MISSING_OBJECT_ID,
          'objectId must not be empty, null or undefined'
        );
      }
    } else {
      if (data.objectId) {
        throw new Parse.Error(Parse.Error.INVALID_KEY_NAME, 'objectId is an invalid field name.');
      }
      if (data.id) {
        throw new Parse.Error(Parse.Error.INVALID_KEY_NAME, 'id is an invalid field name.');
      }
    }
  }

  if (this.config.requestKeywordDenylist) {
    // Scan request data for denied keywords
    const keywords = this.config.requestKeywordDenylist;
    for (let i = 0; i < keywords.length; i++) {
      const keyword = keywords[i];
      const match = Utils.objectContainsKeyValue(data, keyword.key, keyword.value);
      if (match) {
        throw new Parse.Error(
          Parse.Error.INVALID_KEY_NAME,
          `Prohibited keyword in request data: ${JSON.stringify(keyword)}.`
        );
      }
    }
  }

  // When the operation is complete, this.response may have several
  // fields.
  // response: the actual data to be returned
  // status: the http status code. if not present, treated like a 200
  // location: the location header. if not present, no location header
  this.response = null;

  // Processing this operation may mutate our data, so we operate on a
  // copy
  this.query = deepcopy(query);
  this.data = deepcopy(data);
  // We never change originalData, so we do not need a deep copy
  this.originalData = originalData;

  // The timestamp we'll use for this whole operation
  this.updatedAt = Parse._encode(new Date()).iso;

  // Shared SchemaController to be reused to reduce the number of loadSchema() calls per request
  // Once set the schemaData should be immutable
  this.validSchemaController = null;
}

