function viteServeRawFsMiddleware(req, res, next) {
    const requestUrl = new URL(req.url!, 'http://example.com')
    // In some cases (e.g. linked monorepos) files outside of root will
    // reference assets that are also out of served root. In such cases
    // the paths are rewritten to `/@fs/` prefixed paths and must be served by
    // searching based from fs root.
    if (requestUrl.pathname.startsWith(FS_PREFIX)) {
      const decodedPath = decodeURIComponent(requestUrl.pathname)
      // restrict files outside of `fs.allow`
      if (
        !ensureServingAccess(
          slash(path.resolve(fsPathFromId(decodedPath))),
          server,
          res,
          next,
        )
      ) {
        return
      }

      let modifiedPathname = decodedPath.slice(FS_PREFIX.length)
      if (isWindows) modifiedPathname = modifiedPathname.replace(/^[A-Z]:/i, '')

      requestUrl.pathname = encodeURIComponent(modifiedPathname)
      req.url = requestUrl.href.slice(requestUrl.origin.length)
      serveFromRoot(req, res, next)
    } else {
      next()
    }
  }

