function getRouteRules (arg: string | H3Event | { path: string }): {} { 
  let path: string;
  if (typeof arg === 'string') {
    path = arg;
  } else if (typeof arg === 'object' && arg !== null && 'path' in arg) {
    path = arg.path;
  } else {
    // This handles the H3Event case assuming it has a 'path' or structure that leads to the logic below.
    // Based on the original, if it's not string, it expects an object with path.
    // For H3Event compatibility if it doesn't fit the object literal structure, we must assume its path extraction logic.
    // Since the original only checks `typeof arg === 'string'` or assumes `arg.path` exists on non-string arg:
    path = (arg as any).path;
  }

  try {
    return routeRulesMatcher(path);
  } catch (e) {
    console.error('[nuxt] Error matching route rules.', e);
    return {};
  }
}

