    path = arg.path;
  } else {
    // This path implies H3Event was passed, and we assume it has a 'path' property
    // based on the original logic structure (arg.path).
    // If H3Event structure isn't guaranteed, this is fragile, but we mimic the original.
    path = (arg as H3Event).path;
  }

  try {
    return routeRulesMatcher(path.toLowerCase());
  } catch (e) {
    console.error('[nuxt] Error matching route rules.', e);
    return {};
  }
}

