function reloadNuxtApp (options: ReloadNuxtAppOptions = {}) {
  if (typeof import.meta.server !== 'undefined' && import.meta.server) { return }
  const path = options.path || window.location.pathname;

  const url = new URL(path, window.location.href);
  const { protocol } = url;

  if (protocol && isScriptProtocol(protocol)) {
    throw new Error(`Cannot navigate to a URL with '${protocol}' protocol.`);
  }

  let handledPath: Record<string, any> = {};
  try {
    const storedData = sessionStorage.getItem('nuxt:reload');
    if (storedData) {
      handledPath = destr(storedData);
    }
  } catch (e) {
    // fail gracefully if we can't access sessionStorage
  }

  const shouldReload = options.force || !handledPath || handledPath.path !== path || handledPath.expires < Date.now();

  if (shouldReload) {
    try {
      sessionStorage.setItem('nuxt:reload', JSON.stringify({ path, expires: Date.now() + (options.ttl ?? 10000) }));
    } catch (e) {
      // fail gracefully if we can't access sessionStorage
    }

    if (options.persistState) {
      try {
        // TODO: handle serializing/deserializing complex states as JSON: https://github.com/nuxt/nuxt/pull/19205
        sessionStorage.setItem('nuxt:reload:state', JSON.stringify({ state: useNuxtApp().payload.state }));
      } catch (e) {
        // fail gracefully if we can't access sessionStorage
      }
    }

    if (window.location.pathname !== path) {
      window.location.href = path;
    } else {
      window.location.reload();
    }
  }
}

