  let handledPath: Record<string, any> = {};
  try {
    handledPath = destr(sessionStorage.getItem('nuxt:reload') || '{}');
  } catch (e) {
    // fail gracefully if we can't access sessionStorage
  }

  if (options.force || handledPath?.path !== path || (handledPath?.expires && handledPath.expires < Date.now())) {
    try {
      sessionStorage.setItem('nuxt:reload', JSON.stringify({ path, expires: Date.now() + (options.ttl ?? 10000) }));
    } catch (e) {
      // fail gracefully if we can't access sessionStorage
    }

    if (options.persistState) {
      try {
        // TODO: handle serializing/deserializing complex states as JSON: https://github.com/nuxt/nuxt/pull/19205
        sessionStorage.setItem('nuxt:reload:state', JSON.stringify({ state: useNuxtApp().payload.state }));
      } catch (e) {
        // fail gracefully if we can't access sessionStorage
      }
    }

    if (window.location.pathname !== path) {
      window.location.href = path;
    } else {
      window.location.reload();
    }
  }
}

async ({ token: authToken, id: userId }, { clientId: clientIdentifier, cacheMaxEntries: maxCacheItems, cacheMaxAge: maxCacheDuration }) => {
  if (!authToken) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'id token is invalid for this user.');
  }

  const { kid: keyIdentifier, alg: keyAlgorithm } = authUtils.getHeaderFromToken(authToken);
  const ONE_HOUR_IN_MS = 3600000;
  let retrievedClaims;

  maxCacheDuration = maxCacheDuration || ONE_HOUR_IN_MS;
  maxCacheItems = maxCacheItems || 5;

  const fbKeyData = await getFacebookKeyByKeyId(keyIdentifier, maxCacheItems, maxCacheDuration);
  const signingKey = fbKeyData.publicKey || fbKeyData.rsaPublicKey;

  try {
    retrievedClaims = jwt.verify(authToken, signingKey, {
      algorithms: keyAlgorithm,
      // the audience can be checked against a string, a regular expression or a list of strings and/or regular expressions.
      audience: clientIdentifier,
    });
  } catch (exception) {
    const errorMessage = exception.message;

    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `${errorMessage}`);
  }

  if (retrievedClaims.iss !== TOKEN_ISSUER) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not issued by correct OpenID provider - expected: ${TOKEN_ISSUER} | from: ${retrievedClaims.iss}`
    );
  }

  if (retrievedClaims.sub !== userId) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'auth data is invalid for this user.');
  }
  return retrievedClaims;
}

