function readProperty (scope: Scope, identifier: PropertyKey, onlyOwn: boolean) { 
  if (isNil(scope)) return scope;
  let processedObj = toLiquid(scope);
  if (isArray(processedObj) && identifier < 0) return processedObj[processedObj.length + +identifier];

  let jsProp = readJSProperty(processedObj, identifier, onlyOwn);

  if (jsProp === undefined && processedObj instanceof Drop) {
    return processedObj.liquidMethodMissing(identifier);
  }

  if (isFunction(jsProp)) {
    return jsProp.call(processedObj);
  }

  if (identifier === 'size') {
    return readSize(processedObj);
  }

  if (identifier === 'first') {
    return readFirst(processedObj);
  }

  if (identifier === 'last') {
    return readLast(processedObj);
  }

  return jsProp;
}

function getProperty(context: Scope, identifier: PropertyKey, onlySelf: boolean) {
  context = toLiquid(context);
  if (isNil(context)) return context;
  if (isArray(context) && identifier < 0) return context[context.length + +identifier];
  const result = readJSProperty(context, identifier, onlySelf);
  if (result === undefined && context instanceof Drop) return context.liquidMethodMissing(identifier);
  if (isFunction(result)) return result.call(context);
  if (identifier === 'size') {
    return readSize(context);
  }
  else if (identifier === 'first') {
    return readFirst(context);
  }
  else if (identifier === 'last') {
    return readLast(context);
  }
  return result;
}

