function strip_html (this: FilterImpl, inputStr: string) {
  const processedStr = stringify(inputStr);
  this.context.memoryLimit.use(processedStr.length);
  const replacements = new Map([['<script', '</script>'], ['<style', '</style>'], ['<!--', '-->'], ['<', '>']]);
  let result = '';
  let cursor = 0;
  while (cursor < processedStr.length) {
    const startTagIndex = processedStr.indexOf('<', cursor);
    if (startTagIndex < 0) return result + processedStr.slice(cursor);
    result += processedStr.slice(cursor, startTagIndex);
    for (const [opener, closer] of replacements) {
      if (!processedStr.startsWith(opener, startTagIndex)) continue;
      const endTagIndex = processedStr.indexOf(closer, startTagIndex + opener.length);
      if (endTagIndex >= 0) { cursor = endTagIndex + closer.length; break; }
      replacements.delete(opener);
    }
    if (cursor === startTagIndex) return result + processedStr.slice(startTagIndex);
  }
  return result
}

