    } else {
      child[key] = value;
    }
  }

  visited.delete(parent);

  return child;
}

async function generateGenericState(c: GenericEndpointContext, dataState: StateData, opts?: { cookieName: string }) {
    const uniqueState = generateRandomString(32);
    const strategy = c.context.oauthConfig.storeStateStrategy;

    // Cookie strategy:
    //
    // State data is encrypted into the cookie
    // no verification record created
    if (strategy === "cookie") {
        const encryptedPayload = await symmetricEncrypt({
            key: c.context.secretConfig,
            data: JSON.stringify(dataState),
        });

        const authCookie = c.context.createAuthCookie(
            opts?.cookieName ?? "oauth_state",
            {
                maxAge: 10 * 60, // 10 minutes
            },
        );

        c.setCookie(authCookie.name, encryptedPayload, authCookie.attributes);

        return {
            state: uniqueState,
            codeVerifier: dataState.codeVerifier,
        };
    }

    // Database strategy:
    //
    // state is stored in a signed cookie and sent via OAuth URL
    // the adapter hashes it at rest when storeIdentifier is set
    const authCookie = c.context.createAuthCookie(
        opts?.cookieName ?? "state",
        {
            maxAge: 5 * 60, // 5 minutes
        },
    );

    await c.setSignedCookie(
        authCookie.name,
        uniqueState,
        c.context.secret,
        authCookie.attributes,
    );

    const expiryTime = new Date();
    expiryTime.setMinutes(expiryTime.getMinutes() + 10);

    const verificationResult = await c.context.internalAdapter.createVerificationValue({
        value: JSON.stringify(dataState),
        identifier: uniqueState,
        expiresAt: expiryTime,
    });

    if (!verificationResult) {
        throw new StateError(
            "Unable to create verification. Make sure the database adapter is properly working and there is a verification table in the database",
            {
                code: "state_generation_error",
            },
        );
    }

    // Return the plain state, not verification.identifier.
    // The adapter hashes it for DB storage when storeIdentifier is "hashed",
    // so returning verification.identifier would cause double-hashing on lookup.
    return {
        state: uniqueState,
        codeVerifier: dataState.codeVerifier,
    };
}

async function generateGenericState(
  ctx: GenericEndpointContext,
  inputData: StateData,
  optionalSettings?: { cookieName: string },
): Promise<{ state: string; codeVerifier: string }> {
  const uniqueToken = generateRandomString(32);
  const storageMethod = ctx.context.oauthConfig.storeStateStrategy;

  // Cookie strategy:
  //
  // State data is encrypted into the cookie
  //no verification record created
  if (storageMethod === "cookie") {
    const payloadObject: StateData = { ...inputData, oauthState: uniqueToken };
    const encryptedContent = await symmetricEncrypt({
      key: ctx.context.secretConfig,
      data: JSON.stringify(payloadObject),
    });

    const stateCookieObject = ctx.context.createAuthCookie(
      optionalSettings?.cookieName ?? "oauth_state",
      {
        maxAge: 10 * 60, // 10 minutes
      },
    );

    ctx.setCookie(stateCookieObject.name, encryptedContent, stateCookieObject.attributes);

    return {
      state: uniqueToken,
      codeVerifier: inputData.codeVerifier,
    };
  }

  // Database strategy:
  //
  // state is stored in a signed cookie and sent via OAuth URL
  // the adapter hashes it at rest when storeIdentifier is set
  const stateCookieObject = ctx.context.createAuthCookie(
    optionalSettings?.cookieName ?? "state",
    {
      maxAge: 5 * 60, // 5 minutes
    },
  );

  await ctx.setSignedCookie(
    stateCookieObject.name,
    uniqueToken,
    ctx.context.secret,
    stateCookieObject.attributes,
  );

  const expiryTime = new Date();
  expiryTime.setMinutes(expiryTime.getMinutes() + 10);

  const verificationResult = await ctx.context.internalAdapter.createVerificationValue({
    value: JSON.stringify({
      ...inputData,
      oauthState: uniqueToken,
    } satisfies StateData),
    identifier: uniqueToken,
    expiresAt: expiryTime,
  });

  if (!verificationResult) {
    throw new StateError(
      "Unable to create verification. Make sure the database adapter is properly working and there is a verification table in the database",
      {
        code: "state_generation_error",
      },
    );
  }

  // Return the plain state, not verification.identifier.
  // The adapter hashes it for DB storage when storeIdentifier is "hashed",
  // so returning verification.identifier would cause double-hashing on lookup.
  return {
    state: uniqueToken,
    codeVerifier: inputData.codeVerifier,
  };
}

