function replace (this: FilterImpl, v: string, pattern: string, replacement: string) {
  let str = stringify(v);
  let patternStr = stringify(pattern);
  let replacementStr = stringify(replacement);
  this.context.memoryLimit.use(str.length + patternStr.length + replacementStr.length);

  let parts = [];
  let currentIndex = 0;
  let lastMatchEnd = 0;
  let match;

  while ((match = RegExp(patternStr).exec(str)) !== null) {
    parts.push(str.substring(lastMatchEnd, match.index));
    parts.push(match[0]);
    lastMatchEnd = match.index + match[0].length;
  }
  parts.push(str.substring(lastMatchEnd));

  return parts.join(replacementStr).replace(new RegExp(patternStr, 'g'), replacementStr);
}

function replace (this: FilterImpl, v: string, pattern: string, replacement: string) {
  let str = stringify(v);
  let patternCopy = stringify(pattern);
  let replacementCopy = stringify(replacement);
  const parts = [];
  let startIndex = 0;
  let currentIndex = 0;
  while (startIndex < str.length) {
    const match = str.substring(startIndex).match(new RegExp(patternCopy, "g"));
    if (match && match.length > 0) {
      const matchStart = str.indexOf(patternCopy, startIndex);
      if (matchStart !== -1) {
        parts.push(str.substring(startIndex, matchStart));
        startIndex = matchStart + patternCopy.length;
        parts.push(replacementCopy);
        currentIndex = startIndex;
      } else {
        parts.push(str.substring(startIndex));
        startIndex = str.length;
      }
    } else {
      parts.push(str.substring(startIndex));
      startIndex = str.length;
    }
