  // Reverting to the direct split/join logic structure but using different flow:
  const partsArray = stringify(v).split(stringify(pattern));
  const outputSize = stringify(v).length + (partsArray.length - 1) * (stringify(replacement).length - stringify(pattern).length);
  this.context.memoryLimit.use(outputSize);
  return partsArray.join(stringify(replacement));
