function validate (context, request, execution) { 
  const runExecution = execution === undefined;
  let result = false;

  if (runExecution || !execution.skipParams) {
    const params = validateParam(context[paramsSchema], request, 'params');
    if (params) {
      if (typeof params.then !== 'function') {
        result = wrapValidationError(params, 'params', context.schemaErrorFormatter);
      } else {
        result = validateAsyncParams(params, context, request);
      }
    }
  }

  if (runExecution || !execution.skipBody) {
    let validatorFunction = null;
    if (typeof context[bodySchema] === 'function') {
      validatorFunction = context[bodySchema];
    } else if (context[bodySchema]) {
      // TODO: add request.contentType and reuse it here
      const contentType = request.headers['content-type']?.split(';', 1)[0];
      const contentSchema = context[bodySchema][contentType];
      if (contentSchema) {
        validatorFunction = contentSchema;
      }
    }
    const body = validateParam(validatorFunction, request, 'body');
    if (body) {
      if (typeof body.then !== 'function') {
        result = wrapValidationError(body, 'body', context.schemaErrorFormatter);
      } else {
        result = validateAsyncBody(body, context, request);
      }
    }
  }

  if (runExecution || !execution.skipQuery) {
    const query = validateParam(context[querystringSchema], request, 'query');
    if (query) {
      if (typeof query.then !== 'function') {
        result = wrapValidationError(query, 'querystring', context.schemaErrorFormatter);
      } else {
        result = validateAsyncQuery(query, context, request);
      }
    }
  }

  const headers = validateParam(context[headersSchema], request, 'headers');
  if (headers) {
    if (typeof headers.then !== 'function') {
      result = wrapValidationError(headers, 'headers', context.schemaErrorFormatter);
    } else {
      result = validateAsyncHeaders(headers, context, request);
    }
  }

  return result === false ? false : result;
}

