    const pathname = decodeURI(url.pathname)

    // apply aliases to static requests as well
    let redirectedPathname: string | undefined;
    for (const { find, replacement } of server.config.resolve.alias) {
      const matches = 
        typeof find === 'string' 
          ? pathname.startsWith(find)
          : find.test(pathname);
      if (matches) {
        redirectedPathname = pathname.replace(find, replacement);
        break;
      }
    }
    if (redirectedPathname) {
      // dir is pre-normalized to posix style
      if (redirectedPathname.startsWith(withTrailingSlash(dir))) {
        redirectedPathname = redirectedPathname.slice(dir.length);
      }
    }

    const resolvedPathname = redirectedPathname || pathname;
    let fileUrl = path.resolve(dir, removeLeadingSlash(resolvedPathname));
    if (resolvedPathname.endsWith('/') && fileUrl[fileUrl.length - 1] !== '/') {
      fileUrl = withTrailingSlash(fileUrl);
    }
    if (!ensureServingAccess(fileUrl, server, res, next)) {
      return;
    }

    if (redirectedPathname) {
      url.pathname = encodeURI(redirectedPathname);
      req.url = url.href.slice(url.origin.length);
    }

    serve(req, res, next);
  }

function viteServeStaticMiddleware(req, res, next) {
    // only serve the file if it's not an html request or ends with `/`
    // so that html requests can fallthrough to our html middleware for
    // special processing
    // also skip internal requests `/@fs/ /@vite-client` etc...
    const cleanedUrl = cleanUrl(req.url!)
    const shouldSkip = (
      cleanedUrl.endsWith('/') ||
      path.extname(cleanedUrl) === '.html' ||
      isInternalRequest(req.url!) ||
      // skip url starting with // as these will be interpreted as
      // scheme relative URLs by new URL() and will not be a valid file path
      req.url?.startsWith('//')
    );

    if (shouldSkip) {
      return next();
    }

    const url = new URL(req.url!, 'http://example.com');
    const pathname = decodeURI(url.pathname);

    // apply aliases to static requests as well
    let redirectedPathname: string | undefined = undefined;
    for (const { find, replacement } of server.config.resolve.alias) {
      const matches = (
        typeof find === 'string'
          ? pathname.startsWith(find)
          : find.test(pathname)
      );
      if (matches) {
        redirectedPathname = pathname.replace(find, replacement);
        break;
      }
    }
    if (redirectedPathname) {
      // dir is pre-normalized to posix style
      if (redirectedPathname.startsWith(withTrailingSlash(dir))) {
        redirectedPathname = redirectedPathname.slice(dir.length);
      }
    }

    const resolvedPathname = redirectedPathname || pathname;
    let fileUrl = path.resolve(dir, removeLeadingSlash(resolvedPathname));
    if (resolvedPathname.endsWith('/') && fileUrl[fileUrl.length - 1] !== '/') {
      fileUrl = withTrailingSlash(fileUrl);
    }
    if (redirectedPathname) {
      url.pathname = encodeURI(redirectedPathname);
      req.url = url.href.slice(url.origin.length);
    }

    try {
      serve(req, res, next);
    } catch (e) {
      if (e && 'code' in e && e.code === ERR_DENIED_FILE) {
        respondWithAccessDenied(e.path, server, res);
        return;
      }
      throw e;
    }
  }

async metadataHandler(request, response) {
    try {
      const appConfig = Config.get(request.params.appId);
      if (!appConfig) {
        response.status(200);
        response.json({});
        return;
      }
      const { filesController } = appConfig;
      let { filename } = request.params;
      const fileObject = new Parse.File(filename, { base64: '' });
      const triggerOutcome = await triggers.maybeRunFileTrigger(
        triggers.Types.beforeFind,
        { file: fileObject },
        appConfig,
        request.auth
      );
      if (triggerOutcome?.file?._name) {
        filename = triggerOutcome.file._name;
      }
      let metadataData = await filesController.getMetadata(filename).catch(() => {
        response.status(200);
        response.json({});
      });
      if (!metadataData) {
        return;
      }
      await triggers.maybeRunFileTrigger(
        triggers.Types.afterFind,
        { file: fileObject },
        appConfig,
        request.auth
      );
      response.status(200);
      response.json(metadataData);
    } catch (error) {
      const resolvedError = triggers.resolveError(error, {
        code: Parse.Error.SCRIPT_FAILED,
        message: 'Could not get file metadata.',
      });
      response.status(403);
      response.json({ code: resolvedError.code, error: resolvedError.message });
    }
  }

async metadataHandler(request, response) {
    try {
      const appConfig = Config.get(request.params.appId);
      if (!appConfig) {
        response.status(200);
        response.json({});
        return;
      }
      const { filesController } = appConfig;
      let { filename } = request.params;
      const fileObject = new Parse.File(filename, { base64: '' });
      const authContext = await FilesRouter._resolveAuth(request, appConfig);

      const triggerResult = await triggers.maybeRunFileTrigger(
        triggers.Types.beforeFind,
        { file: fileObject },
        appConfig,
        authContext
      );

      if (triggerResult?.file?._name) {
        filename = triggerResult.file._name;
      }

      let data;
      data = await filesController.getMetadata(filename).catch(() => {
        response.status(200);
        response.json({});
        return null;
      });

      if (!data) {
        return;
      }

      await triggers.maybeRunFileTrigger(
        triggers.Types.afterFind,
        { file: fileObject },
        appConfig,
        authContext
      );

      response.status(200);
      response.json(data);
    } catch (e) {
      const errorDetails = triggers.resolveError(e, {
        code: Parse.Error.SCRIPT_FAILED,
        message: 'Could not get file metadata.',
      });
      response.status(403);
      response.json({ code: errorDetails.code, error: errorDetails.message });
    }
  }

function(name) {
    const result = [];
    result.push(this.aliasable('container.lookup'));
    result.push(`(depths, "${name}")`);
    return result;
}

function(param) {
    const result = [
      this.aliasable('container.lookup'),
      '(depths, ',
      JSON.stringify(param),
      ')'
    ];
    return result;
}
